 function n(v){return Number(v)||0} function esc(v){return _rp2Esc(String(v==null?'':v))} function money(v){return _rp2$(n(v))} function clean(v){return String(v==null?'':v).trim()} function norm(v){return clean(v).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()} function arr(v){if(Array.isArray(v))return v;if(!v)return[];if(typeof v==='object')return Object.keys(v).map(function(k){return v[k]}).filter(Boolean);return[]} function stamp(v){if(!v)return null;var d=new Date(v);return isNaN(d.getTime())?null:d} function day(v){var d=stamp(v);if(d)d.setHours(12,0,0,0);return d} function now(){return window._rp2AccountPlansNow?new Date(window._rp2AccountPlansNow):new Date()} function iso(v){var d=stamp(v);return d?d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'):''} function fmt(v){var d=stamp(v);return d?d.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—'} function days(a,b){var x=day(a),y=day(b);return x&&y?Math.round((y-x)/86400000):null} function id(p){return p+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7)} function field(o,names,def){for(var i=0;i<names.length;i++){var v=o&&o[names[i]];if(v!=null&&String(v).trim()!=='')return v}return def==null?'':def} function companyOf(o){return clean(field(o,['company','customer','account','accountName','companyName'],'')||'')} function repOkay(o){var r=clean(field(o,['rep','owner','salesRep','repName'],'')||'');return !r||r===_rp2.rep} function read(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch(e){return null}}
 function planStore(){var s=read(STORE);if(!s||s.version!==1||!s.reps)s={version:1,reps:{}};s.reps[_rp2.rep]=s.reps[_rp2.rep]||{plans:{},events:[]};s.reps[_rp2.rep].plans=s.reps[_rp2.rep].plans||{};s.reps[_rp2.rep].events=arr(s.reps[_rp2.rep].events);return{store:s,data:s.reps[_rp2.rep]}} function savePlanStore(b){b.store.reps[_rp2.rep]=b.data;localStorage.setItem(STORE,JSON.stringify(b.store))} function audit(type,title,copy,itemId){var b=planStore();b.data.events.push({id:id('apev'),type:type,title:title,copy:copy,itemId:itemId,at:new Date().toISOString()});savePlanStore(b)}
 function repCrm(){var s=read(CRM_STORE);if(!s||s.version!==1||!s.reps)s={version:1,reps:{}};s.reps[_rp2.rep]=s.reps[_rp2.rep]||{accounts:{}};return{store:s,data:s.reps[_rp2.rep]}} function findAccountKey(name,b){var target=norm(name),keys=Object.keys(b.data.accounts||{});if(b.data.accounts[target])return target;for(var i=0;i<keys.length;i++){var a=b.data.accounts[keys[i]]||{};if(norm(a.profile&&a.profile.name)===target)return keys[i]}return target} function account(name,create){var b=repCrm(),k=findAccountKey(name,b);if(create!==false)b.data.accounts[k]=b.data.accounts[k]||{profile:{name:name,owner:_rp2.rep,lifecycle:'Prospect',tier:'Standard',status:'Active',tags:[]},contacts:[],opportunities:[],activities:[],quotes:[],notes:[],files:[]};var a=b.data.accounts[k];if(a){a.contacts=arr(a.contacts);a.opportunities=arr(a.opportunities);a.activities=arr(a.activities);a.quotes=arr(a.quotes)}return{store:b.store,rep:b.data,key:k,data:a}} function saveAccount(b){b.rep.accounts[b.key]=b.data;b.store.reps[_rp2.rep]=b.rep;localStorage.setItem(CRM_STORE,JSON.stringify(b.store))}
 function actions(){var s=read(ACTION_STORE);if(!s||s.version!==1||!s.reps)s={version:1,reps:{}};s.reps[_rp2.rep]=s.reps[_rp2.rep]||{manual:[],state:{},events:[]};s.reps[_rp2.rep].manual=arr(s.reps[_rp2.rep].manual);s.reps[_rp2.rep].state=s.reps[_rp2.rep].state||{};s.reps[_rp2.rep].events=arr(s.reps[_rp2.rep].events);return{store:s,data:s.reps[_rp2.rep]}} function saveActions(b){b.store.reps[_rp2.rep]=b.data;localStorage.setItem(ACTION_STORE,JSON.stringify(b.store))}
 function companies(){var map={},b=repCrm();Object.keys(b.data.accounts||{}).forEach(function(k){var a=b.data.accounts[k]||{},name=clean(a.profile&&a.profile.name)||k;if(name)map[norm(name)]=name});arr(S&&S.orders).forEach(function(o){if(o&&o.rep===_rp2.rep&&clean(o.customer))map[norm(o.customer)]=clean(o.customer)});return Object.keys(map).map(function(k){return map[k]}).sort()}
 function orders(name){var key=norm(name);return arr(S&&S.orders).filter(function(o){return o&&o.rep===_rp2.rep&&norm(o.customer)===key&&!/quote|proposal|estimate/i.test(String(o.kind||'')+' '+String(o.status||''))}).map(function(o){return{date:stamp(o.orderDate||o.date||o.enteredAt),value:n(o.total||o.amount),number:clean(o.orderNum||o.number||o.id),category:clean(o.category||o.productCategory||o.product||o.description||'Order')}}).sort(function(a,b){return (a.date?a.date.getTime():0)-(b.date?b.date.getTime():0)})}
 function connectedContacts(name){var key=norm(name),rows=[];[S&&S.accountContacts,S&&S.customerContacts,S&&S.crmContacts,S&&S.contacts].forEach(function(pool){arr(pool).forEach(function(c){if(c&&repOkay(c)&&norm(companyOf(c))===key)rows.push({id:String(field(c,['id','contactId'],id('ct'))),name:clean(field(c,['name','contactName','fullName'],'Unnamed contact')),title:clean(field(c,['title','jobTitle'],'')),buyingRole:clean(field(c,['buyingRole','role','contactRole'],'Contact')),decisionMaker:!!field(c,['decisionMaker','isDecisionMaker'],false),influence:clean(field(c,['influence','influenceLevel'],'Unknown')),lastTouch:stamp(field(c,['lastTouch','lastContact'],'')),nextTouch:stamp(field(c,['nextTouch','nextContact'],'')),source:'connected'})})});return rows}
 function contacts(name){var b=account(name,false),rows=b.data?arr(b.data.contacts).map(function(c){return{id:String(c.id||id('ct')),name:clean(c.name)||'Unnamed contact',title:clean(c.title),buyingRole:clean(c.buyingRole||c.role||'Contact'),decisionMaker:!!c.decisionMaker,influence:clean(c.influence||'Unknown'),lastTouch:stamp(c.lastTouch),nextTouch:stamp(c.nextTouch),source:'local'}}):[];return rows.concat(connectedContacts(name))}
 function opportunities(name){var key=norm(name),rows=[],b=account(name,false);if(b.data)arr(b.data.opportunities).forEach(function(o){rows.push({id:String(o.id),title:clean(o.title||o.name||'Opportunity'),stage:clean(o.stage||'Discovery'),amount:n(o.amount||o.value),nextStep:clean(o.nextStep),nextDate:stamp(o.nextStepDate),source:'local'})});[S&&S.opportunities,S&&S.crmOpportunities,S&&S.accountOpportunities].forEach(function(pool){arr(pool).forEach(function(o){if(o&&repOkay(o)&&norm(companyOf(o))===key)rows.push({id:String(field(o,['id','opportunityId'],id('op'))),title:clean(field(o,['title','name','opportunity'],'Opportunity')),stage:clean(field(o,['stage'],'Discovery')),amount:n(field(o,['amount','value'],0)),nextStep:clean(field(o,['nextStep','action'],'')),nextDate:stamp(field(o,['nextStepDate','followUpDate'],'')),source:'connected'})})});return rows}
 function quality(name){var key=norm(name),art=arr(S&&S.artErrors).filter(function(x){return x&&repOkay(x)&&norm(companyOf(x))===key}).length,cms=arr(S&&S.cms).filter(function(x){return x&&repOkay(x)&&norm(companyOf(x))===key&&String(x.fault||'')==='rep'}).length,reviews=arr(S&&S.reviews).filter(function(x){return x&&repOkay(x)&&norm(companyOf(x))===key&&!x.removed}).map(function(x){return n(x.rating||x.stars)}).filter(Boolean);return{art:art,cms:cms,reviews:reviews.length,avg:reviews.length?reviews.reduce(function(s,x){return s+x},0)/reviews.length:null}}
 function normalizePlan(name,p){p=p||{};return{company:name,status:clean(p.status||'Draft'),tier:clean(p.tier||'Standard'),owner:clean(p.owner||_rp2.rep),reviewDate:stamp(p.reviewDate),planYear:n(p.planYear||now().getFullYear()),objective:clean(p.objective),customerGoals:clean(p.customerGoals),successDefinition:clean(p.successDefinition),relationshipStrategy:clean(p.relationshipStrategy),strengths:clean(p.strengths),risks:clean(p.risks),opportunitiesText:clean(p.opportunitiesText),blockers:clean(p.blockers),growthPotential:n(p.growthPotential),retentionConfidence:n(p.retentionConfidence||50),stakeholders:arr(p.stakeholders),programs:arr(p.programs),growthIdeas:arr(p.growthIdeas),goals:arr(p.goals),priorities:arr(p.priorities),history:arr(p.history),createdAt:stamp(p.createdAt),updatedAt:stamp(p.updatedAt)}}
 function planFor(name){var b=planStore(),k=norm(name);return normalizePlan(name,b.data.plans[k])} function savePlan(p,type,copy){var b=planStore(),k=norm(p.company);p.updatedAt=new Date().toISOString();if(!p.createdAt)p.createdAt=p.updatedAt;p.history=arr(p.history);p.history.push({type:type||'Plan updated',copy:copy||'',at:p.updatedAt});b.data.plans[k]=p;savePlanStore(b);audit(type||'Plan updated',p.company,copy||p.status,k)}
 function evidence(name){var ord=orders(name),cts=contacts(name),opps=opportunities(name),q=quality(name),today=now(),last=ord.length?ord[ord.length-1].date:null,currentYear=today.getFullYear(),priorYear=currentYear-1,cy=ord.filter(function(o){return o.date&&o.date.getFullYear()===currentYear}).reduce(function(s,o){return s+o.value},0),py=ord.filter(function(o){return o.date&&o.date.getFullYear()===priorYear}).reduce(function(s,o){return s+o.value},0),life=ord.reduce(function(s,o){return s+o.value},0),open=opps.filter(function(o){return !/won|lost|closed/i.test(o.stage)}),next=cts.filter(function(c){return c.nextTouch}).sort(function(a,b){return a.nextTouch-b.nextTouch})[0],dms=cts.filter(function(c){return c.decisionMaker||/decision|owner|executive|procurement/i.test(c.buyingRole)});return{orders:ord,contacts:cts,opps:opps,quality:q,lastOrder:last,daysSince:last?days(last,today):null,currentYear:cy,priorYear:py,lifetime:life,orderCount:ord.length,openOpps:open,openValue:open.reduce(function(s,o){return s+o.amount},0),nextTouch:next&&next.nextTouch,decisionMakers:dms}}
 function health(plan,e){var score=0,parts=[];function add(label,pts,max){score+=pts;parts.push({label:label,pts:pts,max:max})}add('Order recency',e.daysSince==null?0:e.daysSince<=90?20:e.daysSince<=180?14:e.daysSince<=365?7:0,20);add('Relationship coverage',Math.min(20,e.contacts.length*5+(e.decisionMakers.length?5:0)),20);add('Next-step coverage',e.nextTouch||plan.priorities.some(function(x){return x.dueDate})?15:0,15);add('Strategic plan completeness',[plan.objective,plan.customerGoals,plan.successDefinition,plan.relationshipStrategy].filter(Boolean).length*5,20);add('Growth motion',Math.min(15,plan.programs.length*3+plan.growthIdeas.length*3+e.openOpps.length*4),15);add('Quality confidence',Math.max(0,10-e.quality.art*2-e.quality.cms*3+(e.quality.avg&&e.quality.avg>=4.5?2:0)),10);return{score:Math.round(Math.min(100,score)),parts:parts}}
 function risks(plan,e){var r=[];function add(level,icon,title,copy,weight){r.push({level:level,icon:icon,title:title,copy:copy,weight:weight,company:plan.company})}if(e.daysSince==null)add('medium','◷','No visible order history','This account has no connected completed-order evidence.',20);else if(e.daysSince>365)add('high','◷','Account is dormant',e.daysSince+' days since the latest visible order.',45);else if(e.daysSince>180)add('medium','◷','Order recency is weakening',e.daysSince+' days since the latest visible order.',25);if(e.currentYear<e.priorYear*.7&&e.priorYear>0)add('high','↘','Year-over-year revenue is down',money(e.currentYear)+' this year versus '+money(e.priorYear)+' last year.',42);if(!e.decisionMakers.length)add('high','👤','Decision-maker coverage is missing','No visible contact is marked or described as a decision maker.',35);if(e.contacts.length<2)add('medium','⛓','Relationship is single-threaded',e.contacts.length+' visible contact'+(e.contacts.length===1?'':'s')+'.',24);if(!e.nextTouch&&!plan.priorities.some(function(x){return x.dueDate&&!x.completed}))add('medium','📅','No future relationship action','No next contact or open dated plan priority is visible.',26);if(!plan.reviewDate)add('medium','🧭','Plan review is not scheduled','The account plan has no review date.',18);else if(plan.reviewDate<now())add('high','🧭','Plan review is overdue','Review was due '+fmt(plan.reviewDate)+'.',32);if(e.quality.art||e.quality.cms)add('medium','⚠','Quality recovery context exists',e.quality.art+' art errors and '+e.quality.cms+' rep-fault credit memos are visible.',28);return r.sort(function(a,b){return b.weight-a.weight})}
 function growth(plan,e){var g=[];function add(icon,title,copy,value,evidence){g.push({icon:icon,title:title,copy:copy,value:value||0,evidence:evidence})}if(e.orderCount&&plan.programs.length===0)add('📅','Map the annual reorder calendar','Turn past ordering into a planned annual cadence.',0,e.orderCount+' historical orders');if(e.contacts.length<3)add('👥','Expand stakeholder coverage','Add operations, finance, HR, art, or executive relationships.',0,e.contacts.length+' visible contacts');if(e.currentYear<e.priorYear&&e.priorYear>0)add('↗','Recover prior-year volume','Identify which program or timing changed.',Math.max(0,e.priorYear-e.currentYear),money(e.priorYear-e.currentYear)+' year-over-year gap');if(!e.openOpps.length)add('◆','Create a defined growth opportunity','Convert a validated customer need into the opportunity pipeline.',plan.growthPotential,'No open opportunity evidence');plan.growthIdeas.forEach(function(x){if(!x.completed)add('✦',x.title||'Growth idea',x.description||x.nextStep||'',n(x.potential),x.evidence||'Account-plan hypothesis')});return g}
 function build(){var names=companies(),rows=names.map(function(name){var p=planFor(name),e=evidence(name),h=health(p,e);p.health=h;p.evidence=e;p.riskRows=risks(p,e);p.growthRows=growth(p,e);return p}),planned=rows.filter(function(p){return p.createdAt||p.objective||p.programs.length||p.priorities.length}),active=planned.filter(function(p){return ['Active','Review Due','At Risk'].indexOf(p.status)>=0}),atRisk=rows.filter(function(p){return p.riskRows.some(function(r){return r.level==='high'})}),reviewDue=planned.filter(function(p){return p.reviewDate&&p.reviewDate<=new Date(now().getTime()+30*86400000)}),growthPotential=planned.reduce(function(s,p){return s+p.growthPotential+p.growthIdeas.reduce(function(a,x){return a+n(x.potential)},0)},0),actual=rows.reduce(function(s,p){return s+p.evidence.currentYear},0),openPriorities=planned.reduce(function(s,p){return s+p.priorities.filter(function(x){return !x.completed}).length},0);return{rows:rows,planned:planned,active:active,atRisk:atRisk,reviewDue:reviewDue,growthPotential:growthPotential,actual:actual,openPriorities:openPriorities,events:planStore().data.events}}
 function head(k,t,note){return '<div class="ap3-section-head"><div><div class="ap3-section-kick">'+k+'</div><div class="ap3-section-title">'+t+'</div></div><div class="ap3-section-note">'+note+'</div></div>'} function kpi(l,v,s){return '<div class="ap3-kpi"><div class="ap3-kpi-label">'+esc(l)+'</div><div class="ap3-kpi-value">'+v+'</div><div class="ap3-kpi-sub">'+s+'</div></div>'} function empty(t,c){return '<div class="ap3-empty"><strong>'+esc(t)+'</strong><span>'+esc(c)+'</span></div>'} function tabs(active){return '<div class="ap3-tabs-wrap"><div class="ap3-tabs">'+TABS.map(function(t){return '<button class="ap3-tab '+(t[0]===active?'active':'')+'" onclick="_rp2AccountPlansSetTab(\''+t[0]+'\')">'+t[2]+' '+t[1]+'</button>'}).join('')+'</div></div>'}
 function posture(g){if(!g.planned.length)return{tone:'info',title:'The growth-planning workspace is ready',copy:'Create the first account plan and connect customer goals to relationship and program actions.'};if(g.atRisk.length)return{tone:'risk',title:'Retention risks require an account decision',copy:g.atRisk.length+' account'+(g.atRisk.length===1?' has':'s have')+' at least one high-priority risk signal.'};if(g.reviewDue.length)return{tone:'warn',title:'Strategic account reviews are approaching',copy:g.reviewDue.length+' plan'+(g.reviewDue.length===1?' is':'s are')+' due or overdue within 30 days.'};return{tone:'good',title:'Account plans are active and executable',copy:g.openPriorities+' open priorities connect strategy to rep action.'}}
 function priorityRow(p,r){return '<div class="ap3-priority '+r.level+'"><div class="ap3-priority-icon">'+r.icon+'</div><div><div class="ap3-priority-title">'+esc(p.company+' · '+r.title)+'</div><div class="ap3-priority-copy">'+esc(r.copy)+'</div></div><div class="ap3-priority-side">Health '+p.health.score+'/100<br><button class="ap3-mini-btn warn" onclick="_rp2AccountPlansOpen(\''+encodeURIComponent(p.company)+'\')">Open plan</button></div></div>'}
 function command(g){var p=posture(g),risk=[];g.rows.forEach(function(x){x.riskRows.slice(0,2).forEach(function(r){risk.push({p:x,r:r})})});risk.sort(function(a,b){return b.r.weight-a.r.weight});return head('Growth command center','Protect retention and build the next customer program','Actual order history is shown separately from strategic growth potential and open opportunities.')+'<div class="ap3-summary"><div class="ap3-summary-label">Portfolio interpretation</div><div class="ap3-summary-title">'+esc(p.title)+'</div><div class="ap3-summary-copy">'+esc(p.copy)+'</div></div>'+head('Highest-priority account moves','Relationship, recency, plan-review, and quality signals','Every warning identifies visible evidence; none predicts that the account will churn.')+(risk.length?'<div class="ap3-priority-list">'+risk.slice(0,10).map(function(x){return priorityRow(x.p,x.r)}).join('')+'</div>':empty('No account risks are active','Create account plans to add review dates, goals, programs, and priorities.'))+head('Portfolio health','Transparent account-health score','The score combines recency, relationship coverage, future actions, plan completeness, growth motion, and quality evidence.')+'<div class="ap3-panel"><div class="ap3-chart"><canvas id="ap3-chart"></canvas></div></div>'}
 function filter(g){return '<div class="ap3-filterbar"><input id="ap3-search" placeholder="Search company, objective, program…" oninput="_rp2AccountPlansFilter()"><select id="ap3-status" onchange="_rp2AccountPlansFilter()"><option value="">All plan statuses</option>'+STATUSES.map(function(x){return '<option>'+x+'</option>'}).join('')+'</select><select id="ap3-tier" onchange="_rp2AccountPlansFilter()"><option value="">All tiers</option>'+TIERS.map(function(x){return '<option>'+x+'</option>'}).join('')+'</select><select id="ap3-risk" onchange="_rp2AccountPlansFilter()"><option value="">Any risk state</option><option value="risk">High risk</option><option value="clean">No high risk</option></select><div id="ap3-count" class="ap3-filtercount">'+g.rows.length+' shown</div></div>'}
 function planCard(p){return '<div class="ap3-plan" data-ap517="1" data-status="'+esc(p.status)+'" data-tier="'+esc(p.tier)+'" data-risk="'+(p.riskRows.some(function(r){return r.level==='high'})?'risk':'clean')+'" data-search="'+esc((p.company+' '+p.objective+' '+p.customerGoals+' '+p.programs.map(function(x){return x.title}).join(' ')).toLowerCase())+'" onclick="_rp2AccountPlansOpen(\''+encodeURIComponent(p.company)+'\')"><div class="ap3-plan-name">'+esc(p.company)+'</div><div class="ap3-plan-meta">'+esc(p.status+' · '+p.tier+' · '+p.evidence.orderCount+' orders · '+p.evidence.contacts.length+' contacts')+'</div><div class="ap3-plan-value">'+p.health.score+'/100 health</div><div class="ap3-plan-copy">'+esc(p.objective||'No strategic objective recorded.')+' '+money(p.evidence.currentYear)+' actual this year · '+money(p.growthPotential)+' modeled direct growth potential.</div><div class="ap3-bar"><span style="width:'+p.health.score+'%"></span></div><div class="ap3-tags">'+(p.riskRows.some(function(r){return r.level==='high'})?'<span class="ap3-tag risk">High risk signal</span>':'<span class="ap3-tag good">No high risk</span>')+'<span class="ap3-tag info">'+p.programs.length+' programs</span><span class="ap3-tag warn">'+p.priorities.filter(function(x){return !x.completed}).length+' priorities</span></div></div>'}
 function library(g){return head('Account-plan library','Every visible company with strategic planning context','Companies without a saved plan remain visible so the rep can deliberately choose where deeper planning belongs.')+'<div class="ap3-actions" style="margin-top:0"><button class="ap3-btn primary" onclick="_rp2AccountPlansNew()">＋ New account plan</button></div>'+filter(g)+(g.rows.length?'<div class="ap3-plan-grid">'+g.rows.map(planCard).join('')+'</div>':empty('No companies are visible','Customer and CRM account sources are empty.'))}
 function relationships(g){var cards=[];g.rows.forEach(function(p){p.evidence.contacts.forEach(function(c){cards.push({p:p,c:c})})});return head('Relationship map','Decision makers, influence, contact coverage, and relationship gaps','Relationship coverage uses visible CRM and connected contact records; it never invents a stakeholder.')+(cards.length?'<div class="ap3-map-grid">'+cards.map(function(x){var c=x.c,p=x.p;return '<div class="ap3-map-card"><div class="ap3-map-name">'+esc(c.name)+'</div><div class="ap3-map-role">'+esc(p.company+' · '+(c.buyingRole||c.title||'Contact'))+'</div><div class="ap3-map-copy">Influence: '+esc(c.influence||'Unknown')+' · '+(c.decisionMaker?'Decision maker':'Decision-maker status not confirmed')+'<br>Last touch '+fmt(c.lastTouch)+' · Next touch '+fmt(c.nextTouch)+'</div><div class="ap3-tags">'+(c.decisionMaker?'<span class="ap3-tag good">Decision maker</span>':'<span class="ap3-tag warn">Coverage role</span>')+'<span class="ap3-tag info">'+esc(c.source)+'</span></div></div>'}).join('')+'</div>':empty('No contacts are visible','Add contacts in the Company Profile or Contacts Center.'))+head('Relationship coverage chart','Visible contacts and decision makers by account','The chart displays count evidence—not relationship quality assumptions.')+'<div class="ap3-panel"><div class="ap3-chart"><canvas id="ap3-chart"></canvas></div></div>'}
 function calendar(g){var programs=[];g.planned.forEach(function(p){p.programs.forEach(function(x){programs.push({p:p,x:x})})});programs.sort(function(a,b){return n(a.x.month)-n(b.x.month)});return head('Programs and annual calendar','Map recurring programs, buying windows, owners, value hypotheses, and next steps','Program potential remains a planning hypothesis until converted into a qualified opportunity or quote.')+'<div class="ap3-actions" style="margin-top:0"><button class="ap3-btn primary" onclick="_rp2AccountPlansNewProgram()">＋ Add program</button></div>'+(programs.length?'<div class="ap3-calendar">'+programs.map(function(z){var x=z.x;return '<div class="ap3-calendar-card"><div class="ap3-calendar-month">Month '+(x.month||'TBD')+' · '+esc(x.status||'Planned')+'</div><div class="ap3-calendar-title">'+esc(x.title||x.type||'Customer program')+'</div><div class="ap3-calendar-copy">'+esc(z.p.company+' · '+(x.type||'Program'))+'<br>'+money(x.potential)+' modeled potential<br>'+esc(x.nextStep||'No next step recorded')+'</div><div class="ap3-mini-actions"><button class="ap3-mini-btn blue" onclick="_rp2AccountPlansOpen(\''+encodeURIComponent(z.p.company)+'\')">Open plan</button></div></div>'}).join('')+'</div>':empty('No annual programs are mapped','Add recurring programs such as uniforms, safety apparel, onboarding, events, gifts, or seasonal reorders.'))}
 function growthView(g){var rows=[];g.rows.forEach(function(p){p.growthRows.forEach(function(x){rows.push({p:p,x:x})})});rows.sort(function(a,b){return b.x.value-a.x.value});return head('Growth opportunities','Evidence-backed expansion ideas and account-plan hypotheses','Modeled potential never enters forecast, quote, order, or revenue totals by itself.')+'<div class="ap3-insight-grid"><div class="ap3-insight"><div class="ap3-insight-icon">↗</div><div class="ap3-insight-label">Modeled growth potential</div><div class="ap3-insight-value">'+money(g.growthPotential)+'</div><div class="ap3-insight-copy">Saved plan and growth-idea potential only.</div></div><div class="ap3-insight"><div class="ap3-insight-icon">◆</div><div class="ap3-insight-label">Open opportunity value</div><div class="ap3-insight-value">'+money(g.rows.reduce(function(s,p){return s+p.evidence.openValue},0))+'</div><div class="ap3-insight-copy">Visible opportunity-pipeline evidence.</div></div><div class="ap3-insight"><div class="ap3-insight-icon">📦</div><div class="ap3-insight-label">Actual current-year sales</div><div class="ap3-insight-value">'+money(g.actual)+'</div><div class="ap3-insight-copy">Completed connected order evidence only.</div></div><div class="ap3-insight"><div class="ap3-insight-icon">📅</div><div class="ap3-insight-label">Mapped programs</div><div class="ap3-insight-value">'+g.planned.reduce(function(s,p){return s+p.programs.length},0)+'</div><div class="ap3-insight-copy">Annual customer programs in saved plans.</div></div></div>'+head('Expansion queue','What evidence suggests the next growth conversation','Open the account plan to turn a hypothesis into a dated customer action.')+(rows.length?'<div class="ap3-priority-list">'+rows.slice(0,50).map(function(z){return '<div class="ap3-priority"><div class="ap3-priority-icon">'+z.x.icon+'</div><div><div class="ap3-priority-title">'+esc(z.p.company+' · '+z.x.title)+'</div><div class="ap3-priority-copy">'+esc(z.x.copy+' · Evidence: '+z.x.evidence)+'</div></div><div class="ap3-priority-side">'+(z.x.value?money(z.x.value):'Strategic')+'<br><button class="ap3-mini-btn good" onclick="_rp2AccountPlansOpen(\''+encodeURIComponent(z.p.company)+'\')">Plan action</button></div></div>'}).join('')+'</div>':empty('No growth ideas are active','Create account plans or add growth ideas.'))}
 function riskView(g){var rows=[];g.rows.forEach(function(p){p.riskRows.forEach(function(r){rows.push({p:p,r:r})})});rows.sort(function(a,b){return b.r.weight-a.r.weight});return head('Retention and risk','Recency, revenue change, relationship, future-action, review, and quality evidence','Signals identify risk conditions; they do not claim the customer will leave.')+'<div class="ap3-insight-grid"><div class="ap3-insight"><div class="ap3-insight-icon">🛡</div><div class="ap3-insight-label">Accounts with high risk</div><div class="ap3-insight-value">'+g.atRisk.length+'</div><div class="ap3-insight-copy">At least one high-priority visible signal.</div></div><div class="ap3-insight"><div class="ap3-insight-icon">◷</div><div class="ap3-insight-label">Review due</div><div class="ap3-insight-value">'+g.reviewDue.length+'</div><div class="ap3-insight-copy">Plan review due or within 30 days.</div></div><div class="ap3-insight"><div class="ap3-insight-icon">👥</div><div class="ap3-insight-label">Single-threaded</div><div class="ap3-insight-value">'+g.rows.filter(function(p){return p.evidence.contacts.length<2}).length+'</div><div class="ap3-insight-copy">Fewer than two visible contacts.</div></div><div class="ap3-insight"><div class="ap3-insight-icon">📅</div><div class="ap3-insight-label">No future action</div><div class="ap3-insight-value">'+g.rows.filter(function(p){return !p.evidence.nextTouch&&!p.priorities.some(function(x){return x.dueDate&&!x.completed})}).length+'</div><div class="ap3-insight-copy">No visible next contact or open dated priority.</div></div></div>'+(rows.length?'<div class="ap3-priority-list">'+rows.map(function(z){return priorityRow(z.p,z.r)}).join('')+'</div>':empty('No retention signals are active','No visible account currently triggers the modeled risk checks.'))}
 function actionView(g){var priorities=[];g.planned.forEach(function(p){p.priorities.forEach(function(x){priorities.push({p:p,x:x})})});priorities.sort(function(a,b){return (a.x.completed?1:0)-(b.x.completed?1:0)||((stamp(a.x.dueDate)||new Date(9999,1,1))-(stamp(b.x.dueDate)||new Date(9999,1,1)))});return head('Goals and action plan','Customer objectives translated into measurable rep-owned priorities','Account-plan tasks can be pushed to Action Center while remaining linked to the strategic plan.')+'<div class="ap3-actions" style="margin-top:0"><button class="ap3-btn primary" onclick="_rp2AccountPlansNewPriority()">＋ Add priority</button><button class="ap3-btn blue" onclick="_rp2Go(\'action\')">Open Action Center</button></div>'+(priorities.length?'<div class="ap3-priority-list">'+priorities.map(function(z){var x=z.x;return '<div class="ap3-priority '+(x.completed?'':'medium')+'"><div class="ap3-priority-icon">'+(x.completed?'✓':'→')+'</div><div><div class="ap3-priority-title">'+esc(z.p.company+' · '+(x.title||'Account priority'))+'</div><div class="ap3-priority-copy">'+esc((x.action||x.description||'')+' · Success: '+(x.measure||'Not defined'))+'</div></div><div class="ap3-priority-side">'+fmt(x.dueDate)+'<br>'+(x.completed?'<span class="ap3-tag good">Completed</span>':'<button class="ap3-mini-btn good" onclick="_rp2AccountPlansPushPriority(\''+encodeURIComponent(z.p.company)+'\',\''+encodeURIComponent(x.id)+'\')">Action Center</button>')+'</div></div>'}).join('')+'</div>':empty('No account priorities are saved','Add a strategic priority with an action, due date, and success measure.'))}
 function historyView(g){var rows=[];arr(g.events).forEach(function(e){rows.push({date:stamp(e.at),type:e.type,title:e.title,copy:e.copy})});g.planned.forEach(function(p){p.history.forEach(function(h){rows.push({date:stamp(h.at),type:h.type,title:p.company,copy:h.copy})})});rows=rows.filter(function(r){return r.date}).sort(function(a,b){return b.date-a.date});return head('Plan audit history','Plan creation, edits, programs, priorities, Action Center tasks, and review events','The audit records local plan changes—not customer activity that was not actually performed.')+(rows.length?'<div class="ap3-history">'+rows.slice(0,400).map(function(r){return '<div class="ap3-history-row"><div class="ap3-history-date">'+fmt(r.date)+'</div><div class="ap3-history-type">'+esc(r.type)+'</div><div class="ap3-history-title">'+esc(r.title)+'</div><div class="ap3-history-copy">'+esc(r.copy)+'</div></div>'}).join('')+'</div>':empty('No plan history is recorded','Create or update an account plan to begin the audit trail.'))}
 function fieldHtml(label,idv,value,type,options){if(type==='textarea')return '<div class="ap3-field"><label>'+label+'</label><textarea id="'+idv+'">'+esc(value||'')+'</textarea></div>';if(type==='select')return '<div class="ap3-field"><label>'+label+'</label><select id="'+idv+'">'+options.map(function(o){return '<option value="'+esc(o)+'" '+(String(value||'')===String(o)?'selected':'')+'>'+esc(o)+'</option>'}).join('')+'</select></div>';return '<div class="ap3-field"><label>'+label+'</label><input id="'+idv+'" type="'+(type||'text')+'" value="'+esc(value||'')+'"></div>'}
 function planForm(g,p){return '<div class="ap3-modal-wrap" onclick="if(event.target===this)_rp2AccountPlansClose()"><aside class="ap3-modal"><div class="ap3-modal-head"><div><div class="ap3-modal-icon">🧭</div><div class="ap3-modal-kick">'+(p&&p.createdAt?'Edit strategic account plan':'Create strategic account plan')+'</div><div class="ap3-modal-title">'+esc(p&&p.company||'Choose a company')+'</div><div class="ap3-modal-sub">Connect customer goals, relationship strategy, annual programs, risk, growth hypotheses, and rep-owned priorities.</div></div><button class="ap3-close" onclick="_rp2AccountPlansClose()">×</button></div><div class="ap3-form"><div class="ap3-form-grid-3">'+fieldHtml('Company','ap3-f-company',p&&p.company||'', 'select',g.rows.map(function(x){return x.company}))+fieldHtml('Plan status','ap3-f-status',p&&p.status||'Draft','select',STATUSES)+fieldHtml('Account tier','ap3-f-tier',p&&p.tier||'Standard','select',TIERS)+'</div><div class="ap3-form-grid">'+fieldHtml('Plan review date','ap3-f-review',iso(p&&p.reviewDate),'date')+fieldHtml('Modeled direct growth potential','ap3-f-potential',p&&p.growthPotential||0,'number')+'</div>'+fieldHtml('Strategic objective','ap3-f-objective',p&&p.objective||'','textarea')+fieldHtml('Customer goals','ap3-f-goals',p&&p.customerGoals||'','textarea')+fieldHtml('Definition of customer success','ap3-f-success',p&&p.successDefinition||'','textarea')+fieldHtml('Relationship strategy','ap3-f-relationship',p&&p.relationshipStrategy||'','textarea')+'<div class="ap3-form-grid">'+fieldHtml('Strengths to protect','ap3-f-strengths',p&&p.strengths||'','textarea')+fieldHtml('Retention risks','ap3-f-risks',p&&p.risks||'','textarea')+'</div><div class="ap3-form-grid">'+fieldHtml('Growth opportunities','ap3-f-opportunities',p&&p.opportunitiesText||'','textarea')+fieldHtml('Blockers / constraints','ap3-f-blockers',p&&p.blockers||'','textarea')+'</div></div><div class="ap3-disclosure"><strong>Planning integrity:</strong> modeled growth potential is strategic context only. It does not become forecast, quote, order, or completed revenue.</div><div class="ap3-modal-actions"><button class="ap3-btn" onclick="_rp2AccountPlansClose()">Cancel</button><button class="ap3-btn primary" onclick="_rp2AccountPlansSave()">Save plan</button></div></aside></div>'}
 function detail(g,p){var e=p.evidence;return '<div class="ap3-modal-wrap" onclick="if(event.target===this)_rp2AccountPlansClose()"><aside class="ap3-modal"><div class="ap3-modal-head"><div><div class="ap3-modal-icon">🏢</div><div class="ap3-modal-kick">'+esc(p.status+' · '+p.tier+' account plan')+'</div><div class="ap3-modal-title">'+esc(p.company)+'</div><div class="ap3-modal-sub">Health '+p.health.score+'/100 · '+money(e.currentYear)+' actual current-year sales · '+money(p.growthPotential)+' modeled direct growth potential</div></div><button class="ap3-close" onclick="_rp2AccountPlansClose()">×</button></div><div class="ap3-detail-grid"><div class="ap3-detail"><div class="ap3-detail-label">Strategic objective</div><div class="ap3-detail-value">'+esc(p.objective||'Not recorded')+'</div></div><div class="ap3-detail"><div class="ap3-detail-label">Customer goals</div><div class="ap3-detail-value">'+esc(p.customerGoals||'Not recorded')+'</div></div><div class="ap3-detail"><div class="ap3-detail-label">Actual account evidence</div><div class="ap3-detail-value">Lifetime '+money(e.lifetime)+'\nCurrent year '+money(e.currentYear)+'\nPrior year '+money(e.priorYear)+'\n'+e.orderCount+' orders\nLast order '+fmt(e.lastOrder)+'</div></div><div class="ap3-detail"><div class="ap3-detail-label">Relationship evidence</div><div class="ap3-detail-value">'+e.contacts.length+' visible contacts\n'+e.decisionMakers.length+' decision makers\nNext touch '+fmt(e.nextTouch)+'</div></div><div class="ap3-detail"><div class="ap3-detail-label">Growth motion</div><div class="ap3-detail-value">'+p.programs.length+' mapped programs\n'+p.growthIdeas.length+' growth ideas\n'+e.openOpps.length+' open opportunities\n'+money(e.openValue)+' opportunity value</div></div><div class="ap3-detail"><div class="ap3-detail-label">Review and actions</div><div class="ap3-detail-value">Review '+fmt(p.reviewDate)+'\n'+p.priorities.filter(function(x){return !x.completed}).length+' open priorities</div></div></div>'+head('Programs','Annual and recurring customer programs','Edit the plan to add programs and priorities.')+(p.programs.length?'<div class="ap3-calendar">'+p.programs.map(function(x){return '<div class="ap3-calendar-card"><div class="ap3-calendar-month">Month '+(x.month||'TBD')+' · '+esc(x.status||'Planned')+'</div><div class="ap3-calendar-title">'+esc(x.title||x.type)+'</div><div class="ap3-calendar-copy">'+money(x.potential)+' modeled potential<br>'+esc(x.nextStep||'No next step')+'</div></div>'}).join('')+'</div>':empty('No programs are mapped','Add a program from the Programs & Calendar view.'))+head('Risk and growth evidence','Transparent current-state interpretation','Open the dedicated tabs for full portfolio comparison.')+'<div class="ap3-grid-2"><div class="ap3-priority-list">'+(p.riskRows.length?p.riskRows.map(function(r){return priorityRow(p,r)}).join(''):empty('No modeled risks','No account risk checks are active.'))+'</div><div class="ap3-priority-list">'+(p.growthRows.length?p.growthRows.map(function(x){return '<div class="ap3-priority"><div class="ap3-priority-icon">'+x.icon+'</div><div><div class="ap3-priority-title">'+esc(x.title)+'</div><div class="ap3-priority-copy">'+esc(x.copy+' · '+x.evidence)+'</div></div><div class="ap3-priority-side">'+(x.value?money(x.value):'Strategic')+'</div></div>'}).join(''):empty('No growth ideas','Add growth hypotheses or open opportunities.'))+'</div></div><div class="ap3-modal-actions"><button class="ap3-btn" onclick="_rp2AccountPlansClose()">Close</button><button class="ap3-btn blue" onclick="_rp2AccountPlansOpenCompany(\''+encodeURIComponent(p.company)+'\')">Company Profile</button><button class="ap3-btn" onclick="_rp2AccountPlansAddProgram(\''+encodeURIComponent(p.company)+'\')">Add program</button><button class="ap3-btn" onclick="_rp2AccountPlansAddPriority(\''+encodeURIComponent(p.company)+'\')">Add priority</button><button class="ap3-btn primary" onclick="_rp2AccountPlansEdit(\''+encodeURIComponent(p.company)+'\')">Edit plan</button></div></aside></div>'}
 function programForm(g,company){return '<div class="ap3-modal-wrap" onclick="if(event.target===this)_rp2AccountPlansClose()"><aside class="ap3-modal"><div class="ap3-modal-head"><div><div class="ap3-modal-icon">📅</div><div class="ap3-modal-kick">Add customer program</div><div class="ap3-modal-title">'+esc(company||'Choose account')+'</div></div><button class="ap3-close" onclick="_rp2AccountPlansClose()">×</button></div><div class="ap3-form"><div class="ap3-form-grid">'+fieldHtml('Company','ap3-p-company',company||'', 'select',g.rows.map(function(x){return x.company}))+fieldHtml('Program type','ap3-p-type','Employee Apparel','select',PROGRAM_TYPES)+'</div><div class="ap3-form-grid-3">'+fieldHtml('Program title','ap3-p-title','')+fieldHtml('Buying month','ap3-p-month','', 'number')+fieldHtml('Status','ap3-p-status','Planned','select',['Idea','Planned','Discovery','Opportunity Open','Quoted','Active','Completed','Paused'])+'</div><div class="ap3-form-grid">'+fieldHtml('Modeled potential','ap3-p-potential',0,'number')+fieldHtml('Owner','ap3-p-owner',_rp2.rep)+'</div>'+fieldHtml('Customer objective','ap3-p-objective','','textarea')+fieldHtml('Next step','ap3-p-next','','textarea')+'</div><div class="ap3-modal-actions"><button class="ap3-btn" onclick="_rp2AccountPlansClose()">Cancel</button><button class="ap3-btn primary" onclick="_rp2AccountPlansSaveProgram()">Add program</button></div></aside></div>'}
 function priorityForm(g,company){return '<div class="ap3-modal-wrap" onclick="if(event.target===this)_rp2AccountPlansClose()"><aside class="ap3-modal"><div class="ap3-modal-head"><div><div class="ap3-modal-icon">✓</div><div class="ap3-modal-kick">Add account priority</div><div class="ap3-modal-title">'+esc(company||'Choose account')+'</div></div><button class="ap3-close" onclick="_rp2AccountPlansClose()">×</button></div><div class="ap3-form">'+fieldHtml('Company','ap3-a-company',company||'', 'select',g.rows.map(function(x){return x.company}))+fieldHtml('Priority title','ap3-a-title','')+fieldHtml('Required action','ap3-a-action','','textarea')+'<div class="ap3-form-grid">'+fieldHtml('Due date','ap3-a-due','', 'date')+fieldHtml('Owner','ap3-a-owner',_rp2.rep)+'</div>'+fieldHtml('Success measure','ap3-a-measure','','textarea')+fieldHtml('Strategic reason','ap3-a-why','','textarea')+'</div><div class="ap3-modal-actions"><button class="ap3-btn" onclick="_rp2AccountPlansClose()">Cancel</button><button class="ap3-btn primary" onclick="_rp2AccountPlansSavePriority()">Add priority</button></div></aside></div>'}
 function modal(g){var m=window._rp2AccountPlansModal;if(!m)return'';if(m.mode==='new')return planForm(g,planFor(g.rows[0]&&g.rows[0].company||''));if(m.mode==='program')return programForm(g,m.company?decodeURIComponent(m.company):'');if(m.mode==='priority')return priorityForm(g,m.company?decodeURIComponent(m.company):'');var p=m.company?g.rows.filter(function(x){return x.company===decodeURIComponent(m.company)})[0]:null;if(m.mode==='detail'&&p)return detail(g,p);if(m.mode==='edit'&&p)return planForm(g,p);return''}
 function render(){var page=document.getElementById('rp2-page');if(page)page.innerHTML=window._rp2AccountPlansV3();setTimeout(function(){try{window._rp2AccountPlansDraw();window._rp2AccountPlansFilter()}catch(e){}},0)} function val(idv){var e=document.getElementById(idv);return e?clean(e.value):''}
 window._rp2AccountPlansSetTab=function(t){window._rp2AccountPlansTab=t;window._rp2AccountPlansModal=null;render()} ;window._rp2AccountPlansNew=function(){window._rp2AccountPlansModal={mode:'new'};render()};window._rp2AccountPlansOpen=function(c){window._rp2AccountPlansModal={mode:'detail',company:c};render()};window._rp2AccountPlansEdit=function(c){window._rp2AccountPlansModal={mode:'edit',company:c};render()};window._rp2AccountPlansClose=function(){window._rp2AccountPlansModal=null;render()};window._rp2AccountPlansNewProgram=function(){window._rp2AccountPlansModal={mode:'program'};render()};window._rp2AccountPlansAddProgram=function(c){window._rp2AccountPlansModal={mode:'program',company:c};render()};window._rp2AccountPlansNewPriority=function(){window._rp2AccountPlansModal={mode:'priority'};render()};window._rp2AccountPlansAddPriority=function(c){window._rp2AccountPlansModal={mode:'priority',company:c};render()};
 window._rp2AccountPlansSave=function(){var company=val('ap3-f-company');if(!company)return;var old=planFor(company),p=old;p.company=company;p.status=val('ap3-f-status')||'Draft';p.tier=val('ap3-f-tier')||'Standard';p.reviewDate=val('ap3-f-review');p.growthPotential=n(val('ap3-f-potential'));p.objective=val('ap3-f-objective');p.customerGoals=val('ap3-f-goals');p.successDefinition=val('ap3-f-success');p.relationshipStrategy=val('ap3-f-relationship');p.strengths=val('ap3-f-strengths');p.risks=val('ap3-f-risks');p.opportunitiesText=val('ap3-f-opportunities');p.blockers=val('ap3-f-blockers');savePlan(p,old.createdAt?'Plan updated':'Plan created',p.status+' · '+p.tier);var a=account(company,true);a.data.profile=a.data.profile||{};a.data.profile.name=company;a.data.profile.tier=p.tier;saveAccount(a);window._rp2AccountPlansModal=null;render()}
 window._rp2AccountPlansSaveProgram=function(){var company=val('ap3-p-company'),title=val('ap3-p-title');if(!company||!title)return;var p=planFor(company);p.programs.push({id:id('program'),type:val('ap3-p-type'),title:title,month:n(val('ap3-p-month')),status:val('ap3-p-status'),potential:n(val('ap3-p-potential')),owner:val('ap3-p-owner'),objective:val('ap3-p-objective'),nextStep:val('ap3-p-next'),createdAt:new Date().toISOString()});savePlan(p,'Program added',title+' · '+money(n(val('ap3-p-potential'))));window._rp2AccountPlansModal=null;render()}
 window._rp2AccountPlansSavePriority=function(){var company=val('ap3-a-company'),title=val('ap3-a-title');if(!company||!title)return;var p=planFor(company);p.priorities.push({id:id('priority'),title:title,action:val('ap3-a-action'),dueDate:val('ap3-a-due'),owner:val('ap3-a-owner'),measure:val('ap3-a-measure'),why:val('ap3-a-why'),completed:false,createdAt:new Date().toISOString()});savePlan(p,'Priority added',title+' · '+fmt(val('ap3-a-due')));window._rp2AccountPlansModal=null;render()}
 window._rp2AccountPlansPushPriority=function(c,pid){var company=decodeURIComponent(c),idv=decodeURIComponent(pid),p=planFor(company),x=p.priorities.filter(function(z){return z.id===idv})[0];if(!x)return;var ab=actions(),key='accountplan:'+norm(company)+':'+idv,dup=ab.data.manual.some(function(t){var st=ab.data.state[t.id]||{};return t&&t.accountPlanPriorityKey===key&&st.status!=='completed'});if(!dup){var task={id:id('manual'),source:'manual',category:'customer',tone:'info',score:172,title:x.title+' · '+company,why:x.why||'Strategic account-plan priority.',action:x.action,measure:x.measure,dueDate:x.dueDate,customer:company,accountPlanPriorityKey:key,accountPlanPriorityId:idv,page:'accountplans'};ab.data.manual.push(task);ab.data.events.push({type:'create',taskId:task.id,title:task.title,customer:company,at:new Date().toISOString()});saveActions(ab);savePlan(p,'Priority sent to Action Center',x.title)}render()}
 window._rp2AccountPlansOpenCompany=function(c){var company=decodeURIComponent(c),a=account(company,true);a.data.profile=a.data.profile||{};a.data.profile.name=company;saveAccount(a);window._rp2CompanyOpenKey=encodeURIComponent(norm(company));window._rp2CompanyProfileTab='command';window._rp2CompanyCRMModal=null;_rp2Go('customers')}
 window._rp2AccountPlansFilter=function(){try{var q=val('ap3-search').toLowerCase(),status=val('ap3-status'),tier=val('ap3-tier'),risk=val('ap3-risk'),cards=arr(document.querySelectorAll?document.querySelectorAll('#rp2-page [data-ap517="1"]'):[]),shown=0;cards.forEach(function(c){var ok=(!q||String(c.getAttribute('data-search')||'').indexOf(q)>=0)&&(!status||c.getAttribute('data-status')===status)&&(!tier||c.getAttribute('data-tier')===tier)&&(!risk||c.getAttribute('data-risk')===risk);c.style.display=ok?'block':'none';if(ok)shown++});var e=document.getElementById('ap3-count');if(e)e.textContent=shown+' shown'}catch(e){}}
 window._rp2AccountPlansV3=function(){try{var g=build(),tab=window._rp2AccountPlansTab,p=posture(g),avg=g.rows.length?Math.round(g.rows.reduce(function(s,x){return s+x.health.score},0)/g.rows.length):0;var hero='<div class="ap3-hero"><div class="ap3-hero-grid"><div><div class="ap3-kick">ACCOUNT PLANS & CUSTOMER GROWTH CENTER 3.0 · STRATEGIC ACCOUNT OPERATING SYSTEM · BUILD v517</div><div class="ap3-title">Know the account, protect the relationship, and build the next program deliberately</div><div class="ap3-copy">Combine actual account history, relationship coverage, customer goals, annual program mapping, retention evidence, growth hypotheses, open opportunities, strategic priorities, and Action Center execution in one rep-owned account plan.</div><div class="ap3-pills"><span class="ap3-pill '+p.tone+'">'+esc(p.title)+'</span><span class="ap3-pill info">'+g.planned.length+' saved plans</span><span class="ap3-pill">'+g.openPriorities+' open priorities</span><span class="ap3-pill">Growth potential ≠ forecast or revenue</span></div><div class="ap3-actions"><button class="ap3-btn primary" onclick="_rp2AccountPlansNew()">＋ New account plan</button><button class="ap3-btn good" onclick="_rp2AccountPlansNewPriority()">＋ Strategic priority</button><button class="ap3-btn blue" onclick="_rp2Go(\'customers\')">Open Customers</button></div></div><div class="ap3-brief"><div><div class="ap3-brief-label">Average portfolio health</div><div class="ap3-brief-score">'+avg+'<span>/100</span></div><div class="ap3-brief-title">'+g.atRisk.length+' high-risk accounts · '+g.reviewDue.length+' reviews due · '+money(g.growthPotential)+' modeled growth</div><div class="ap3-brief-copy">Health is a transparent operating score. Growth potential is saved planning context, while actual sales remain controlled by completed connected orders.</div></div><div class="ap3-brief-foot"><span>Actual current-year sales <strong>'+money(g.actual)+'</strong></span><span>Mapped programs <strong>'+g.planned.reduce(function(s,x){return s+x.programs.length},0)+'</strong></span></div></div></div></div>';var ks='<div class="ap3-kpis">'+kpi('Visible companies',g.rows.length,'CRM plus completed-order customers')+kpi('Saved plans',g.planned.length,g.active.length+' active / review / risk')+kpi('Portfolio health',avg+'/100','Transparent operating score')+kpi('Actual current year',money(g.actual),'Completed order evidence')+kpi('Modeled growth',money(g.growthPotential),'Strategic planning only')+kpi('High-risk accounts',g.atRisk.length,'At least one high signal')+kpi('Reviews due',g.reviewDue.length,'Due or next 30 days')+kpi('Open priorities',g.openPriorities,'Rep-owned account actions')+'</div>';var content=tab==='library'?library(g):tab==='relationships'?relationships(g):tab==='calendar'?calendar(g):tab==='growth'?growthView(g):tab==='risk'?riskView(g):tab==='actions'?actionView(g):tab==='history'?historyView(g):command(g);return '<div class="ap3-shell">'+hero+ks+tabs(tab)+content+'</div>'+modal(g)}catch(e){console.error('[Account Plans v517]',e);return '<div class="ap3-shell"><div class="ap3-hero"><div class="ap3-kick">ACCOUNT PLANS & CUSTOMER GROWTH CENTER 3.0 · RECOVERY MODE</div><div class="ap3-title">The account-planning workspace hit a compatibility issue</div><div class="ap3-copy">'+esc(e.message||String(e))+'</div></div></div>'}}
 window._rp2AccountPlansDraw=function(){if(typeof Chart!=='function'||['command','relationships'].indexOf(window._rp2AccountPlansTab)<0)return;var c=document.getElementById('ap3-chart');if(!c)return;var g=build();if(_rp2.apChart){try{_rp2.apChart.destroy()}catch(e){}}if(window._rp2AccountPlansTab==='command'){var rows=g.rows.slice().sort(function(a,b){return b.health.score-a.health.score}).slice(0,20);_rp2.apChart=new Chart(c.getContext('2d'),{type:'bar',data:{labels:rows.map(function(x){return x.company}),datasets:[{label:'Health',data:rows.map(function(x){return x.health.score}),backgroundColor:'rgba(16,185,129,.68)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:100}}}})}else{var r=g.rows.slice().sort(function(a,b){return b.evidence.contacts.length-a.evidence.contacts.length}).slice(0,20);_rp2.apChart=new Chart(c.getContext('2d'),{type:'bar',data:{labels:r.map(function(x){return x.company}),datasets:[{label:'Contacts',data:r.map(function(x){return x.evidence.contacts.length}),backgroundColor:'rgba(0,175,239,.62)',borderRadius:6},{label:'Decision makers',data:r.map(function(x){return x.evidence.decisionMakers.length}),backgroundColor:'rgba(16,185,129,.62)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false}})}}
